+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "captiveportal.h"
+
+#include <QCoreApplication>
+#include <QNetworkAccessManager>
+#include <QNetworkReply>
+
+#include <KIO/OpenUrlJob>
+
+#include <NetworkManagerQt/Manager>
+
+#include <chrono>
+
+using namespace std::chrono_literals;
+
+void CaptivePortal::openLoginPage(const QString &xdgActivationToken)
+{
+    // Browsers can upgrade the check URI to HTTPS (HSTS, HTTPS-only modes), which a captive portal
+    // can't intercept, so open the login page the portal redirects the plain HTTP request to instead
+    static auto manager = new QNetworkAccessManager(QCoreApplication::instance());
+    const QUrl checkUrl(NetworkManager::connectivityCheckUri());
+
+    QNetworkRequest request(checkUrl);
+    request.setAttribute(QNetworkRequest::RedirectPolicyAttribute, QNetworkRequest::ManualRedirectPolicy);
+    request.setTransferTimeout(5s);
+
+    QNetworkReply *reply = manager->get(request);
+    QObject::connect(reply, &QNetworkReply::finished, reply, [reply, checkUrl, xdgActivationToken]() {
+        reply->deleteLater();
+
+        QUrl url = checkUrl;
+        const QUrl target = checkUrl.resolved(reply->attribute(QNetworkRequest::RedirectionTargetAttribute).toUrl());
+        // The redirect comes from an untrusted network, only follow it to a web page
+        if (target != checkUrl && (target.scheme() == QLatin1String("http") || target.scheme() == QLatin1String("https"))) {
+            url = target;
+        }
+
+        auto job = new KIO::OpenUrlJob(url);
+        job->setStartupId(xdgActivationToken.toUtf8());
+        job->start();
+    });
+}
